static void alcohol_calc_build_target_view(AlcoholCalcApp* app) {
    VariableItemList* list = app->target_list;
    VariableItem* item;
    char buf[16];

    app->t_volume = 10.0f;
    app->t_degree_idx = 39; /* 40 */
    app->t_spirit_idx = 95; /* 96 */

    item = variable_item_list_add(list, "Need volume", NUDGE_COUNT, target_volume_changed, app);
    variable_item_set_current_value_index(item, NUDGE_CENTER);
    snprintf(buf, sizeof(buf), "%.1f L", (double)app->t_volume);
    variable_item_set_current_value_text(item, buf);

    item = variable_item_list_add(list, "Need %", DEGREE_COUNT, target_degree_changed, app);
    variable_item_set_current_value_index(item, app->t_degree_idx);
    snprintf(buf, sizeof(buf), "%u%%", degree_from_idx(app->t_degree_idx));
    variable_item_set_current_value_text(item, buf);

    item = variable_item_list_add(list, "Spirit %", DEGREE_COUNT, target_spirit_changed, app);
    variable_item_set_current_value_index(item, app->t_spirit_idx);
    snprintf(buf, sizeof(buf), "%u%%", degree_from_idx(app->t_spirit_idx));
    variable_item_set_current_value_text(item, buf);

    app->t_spirit_item = variable_item_list_add(list, "Take spirit", 1, NULL, app);
    app->t_water_item = variable_item_list_add(list, "Take water", 1, NULL, app);

    target_recalculate(app);

    view_set_previous_callback(variable_item_list_get_view(list), alcohol_calc_navigate_to_menu);
}

/* ---------- About screen ---------- */

static void alcohol_calc_build_about_view(AlcoholCalcApp* app) {
    widget_add_text_box_element(
        app->about_widget,
        0,
        0,
        128,
        64,
        AlignCenter,
        AlignTop,
        "\e#Alcohol Calc\e#\n"
        "Spirit dilution & mixing calculator for Flipper Zero.\n\n"
        "github.com/vtlklr",
        false);

    view_set_previous_callback(widget_get_view(app->about_widget), alcohol_calc_navigate_to_menu);
}

/* ---------- Menu / app lifecycle ---------- */

static void alcohol_calc_submenu_callback(void* context, uint32_t index) {
    AlcoholCalcApp* app = context;
    view_dispatcher_switch_to_view(app->view_dispatcher, index);
}

static bool alcohol_calc_navigation_event_callback(void* context) {
    AlcoholCalcApp* app = context;
    view_dispatcher_stop(app->view_dispatcher);
    return true;
}

static AlcoholCalcApp* alcohol_calc_app_alloc(void) {
    AlcoholCalcApp* app = malloc(sizeof(AlcoholCalcApp));
    memset(app, 0, sizeof(AlcoholCalcApp));

    app->gui = furi_record_open(RECORD_GUI);
    app->view_dispatcher = view_dispatcher_alloc();
    view_dispatcher_set_event_callback_context(app->view_dispatcher, app);
    view_dispatcher_set_navigation_event_callback(
        app->view_dispatcher, alcohol_calc_navigation_event_callback);

    app->submenu = submenu_alloc();
    submenu_add_item(
        app->submenu, "Dilute spirit", AlcoholCalcViewDilute, alcohol_calc_submenu_callback, app);
    submenu_add_item(
        app->submenu, "Mix two spirits", AlcoholCalcViewMix, alcohol_calc_submenu_callback, app);
    submenu_add_item(
        app->submenu,
        "Target volume",
        AlcoholCalcViewTarget,
        alcohol_calc_submenu_callback,
        app);
    submenu_add_item(
        app->submenu, "About", AlcoholCalcViewAbout, alcohol_calc_submenu_callback, app);
    view_dispatcher_add_view(app->view_dispatcher, AlcoholCalcViewMenu, submenu_get_view(app->submenu));

    app->dilute_list = variable_item_list_alloc();
    alcohol_calc_build_dilute_view(app);
    view_dispatcher_add_view(
        app->view_dispatcher, AlcoholCalcViewDilute, variable_item_list_get_view(app->dilute_list));

    app->mix_list = variable_item_list_alloc();
    alcohol_calc_build_mix_view(app);
    view_dispatcher_add_view(
        app->view_dispatcher, AlcoholCalcViewMix, variable_item_list_get_view(app->mix_list));

    app->target_list = variable_item_list_alloc();
    alcohol_calc_build_target_view(app);
    view_dispatcher_add_view(
        app->view_dispatcher, AlcoholCalcViewTarget, variable_item_list_get_view(app->target_list));

    app->about_widget = widget_alloc();
    alcohol_calc_build_about_view(app);
    view_dispatcher_add_view(
        app->view_dispatcher, AlcoholCalcViewAbout, widget_get_view(app->about_widget));

    view_dispatcher_attach_to_gui(app->view_dispatcher, app->gui, ViewDispatcherTypeFullscreen);
    view_dispatcher_switch_to_view(app->view_dispatcher, AlcoholCalcViewMenu);

    return app;
}

static void alcohol_calc_app_free(AlcoholCalcApp* app) {
    view_dispatcher_remove_view(app->view_dispatcher, AlcoholCalcViewMenu);
    view_dispatcher_remove_view(app->view_dispatcher, AlcoholCalcViewDilute);
    view_dispatcher_remove_view(app->view_dispatcher, AlcoholCalcViewMix);
    view_dispatcher_remove_view(app->view_dispatcher, AlcoholCalcViewTarget);
    view_dispatcher_remove_view(app->view_dispatcher, AlcoholCalcViewAbout);

    submenu_free(app->submenu);
    variable_item_list_free(app->dilute_list);
    variable_item_list_free(app->mix_list);
    variable_item_list_free(app->target_list);
    widget_free(app->about_widget);

    view_dispatcher_free(app->view_dispatcher);
    furi_record_close(RECORD_GUI);

    free(app);
}

int32_t alcohol_calc_app(void* p) {
    UNUSED(p);
    AlcoholCalcApp* app = alcohol_calc_app_alloc();

    view_dispatcher_run(app->view_dispatcher);

    alcohol_calc_app_free(app);
    return 0;
}
